import {mountManagerExplorer} from './manager-explorer.js';
import {filterHoldings} from './manager-holding-filters.js';
import {escapeHtml as esc,icon} from './components.js';
import {treemapLayout} from './treemap.js';
const money=n=>Number.isFinite(n)?'$'+n.toLocaleString('en-US',{maximumFractionDigits:0}):'—';
const compact=n=>Number.isFinite(n)?'$'+new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'—';
const count=n=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:0}):'—';
const pct=n=>Number.isFinite(n)?(n>0?'+':'')+n.toLocaleString('en-US',{maximumFractionDigits:2})+'%':'—';
export const quarter=period=>/^\d{4}-\d\d-\d\d$/.test(period||'')?period.slice(0,4)+'년 '+Math.ceil(Number(period.slice(5,7))/3)+'분기':'기준 분기 미제공';
const changes={new:'신규',increased:'증가',reduced:'감소',unchanged:'유지',disposed:'전량 처분',unknown:'비교 불가'};
const kinds={share:'주식',put:'풋 옵션',call:'콜 옵션',principal:'원금 기준 증권'};
const sectorColors=['#7164bf','#477caf','#ae8733','#bb6689','#449879','#647d99','#5f8e40','#c47b38','#308e9e','#917c54','#a36b54'];
const sectorColor=name=>name==='분류 미제공'?'#aab4c0':sectorColors[[...name].reduce((s,c)=>s+c.codePointAt(0),0)%sectorColors.length];
function link(row){return row.ticker?'<a data-nav href="/stock/US/'+encodeURIComponent(row.ticker)+'"><strong>'+esc(row.ticker)+'</strong><span>'+esc(row.name)+'</span></a>':'<strong>'+esc(row.name)+'</strong><small>CUSIP '+esc(row.cusip)+' · 티커 연결 미확인</small>';}
const stateBox=(message,loading=false)=>'<div class="data-state" role="status">'+(loading?'<div class="loading-bars"><i></i><i></i><i></i></div>':icon('empty'))+'<strong>'+esc(message)+'</strong></div>';
export function mountManagers(root,{cik=null}={}){
 if(!cik&&new URLSearchParams(location.search).get('mode')!=='stock')return mountManagerExplorer(root);
 const query=new URLSearchParams(location.search);
 let destroyed=false,controller,searchTimer,ownerTimer,requestVersion=0,data=null,nextPage=null,resize,loadingComparison=false,mapLayout=[];
 const state={q:(query.get('q')||'').slice(0,100),page:1,mode:query.get('mode')==='stock'?'stock':'manager',ticker:null,kind:'share',change:'all',holdingQuery:cik?(new URLSearchParams(location.search).get('holding')||'').slice(0,20):'',sort:query.get('sort')||'value',holdingPage:1,disposedPage:1,period:query.get('period')||'',sector:query.get('sector')||'',weightMin:query.get('weightMin')||'',weightMax:query.get('weightMax')||'',valueMin:query.get('valueMin')||'',valueMax:query.get('valueMax')||''};
 state.change=query.get('change')||'all';state.kind=query.get('kind')||'share';
 function saveFilters(){if(!cik)return;const p=new URLSearchParams();for(const [k,v]of Object.entries({holding:state.holdingQuery,period:state.period,sector:state.sector,weightMin:state.weightMin,weightMax:state.weightMax,valueMin:state.valueMin,valueMax:state.valueMax,sort:state.sort==='value'?'':state.sort,change:state.change==='all'?'':state.change,kind:state.kind==='share'?'':state.kind}))if(v)p.set(k,v);history.replaceState(null,'','/managers/'+cik+(p.size?'?'+p:''));}
 root.className='managers-page';
 root.innerHTML='<div class="page-heading"><div><div class="eyebrow">INSTITUTIONAL HOLDINGS</div><h1>운용사 보유 현황</h1></div><span class="manager-heading-note">미국 13F 공시</span></div><div class="manager-content"></div>';
 const content=root.querySelector('.manager-content');
 async function request(path){controller?.abort();controller=new AbortController();const version=++requestVersion;const response=await fetch(path,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(90000)])});const payload=await response.json();if(destroyed||version!==requestVersion)return null;if(!response.ok)throw new Error(payload.message||'정보를 불러오지 못했습니다.');return payload;}
 function searchShell(){
  const stock=state.mode==='stock';
  content.innerHTML='<section class="surface manager-search-panel"><div class="manager-search-modes" role="group" aria-label="검색 방식"><button data-manager="mode" data-mode="manager" aria-pressed="'+!stock+'">운용사·인물 검색</button><button data-manager="mode" data-mode="stock" aria-pressed="'+stock+'">종목으로 운용사 찾기</button></div><label for="manager-search">'+(stock?'어떤 종목을 보유한 운용사를 찾으세요?':'운용사와 관련 인물을 찾아보세요')+'</label><form class="manager-search-form">'+icon('search')+'<input id="manager-search" type="search" placeholder="'+(stock?'종목명 또는 티커 · 예: 엔비디아, Apple, NVDA':'운용사명 또는 인물명 · 예: Berkshire, 버핏')+'" autocomplete="off" value="'+esc(state.q)+'"><button type="submit" class="primary-button">검색</button></form><div class="manager-search-examples"><span>빠른 검색</span>'+(stock?[['엔비디아','엔비디아'],['애플','애플'],['테슬라','테슬라']]:[['버핏','워런 버핏'],['BlackRock','블랙록'],['Cathie Wood','캐시 우드']]).map(([q,label])=>'<button data-manager="example" data-query="'+q+'">'+label+'</button>').join('')+'</div></section><div class="manager-search-context"></div><div class="manager-results" aria-live="polite"></div><div class="manager-pagination"></div>';
 }
 function managerCards(items){return items.map(m=>'<a class="surface manager-card" data-nav href="/managers/'+m.cik+(state.ticker?'?holding='+encodeURIComponent(state.ticker):'')+'"><div class="manager-card-mark">'+icon('empty')+'</div><div class="manager-card-title"><h2>'+esc(m.name)+'</h2><p>'+esc(m.people?.join(' · ')||'기관 운용사')+'</p><small>CIK '+esc(m.cik.padStart(10,'0'))+'</small></div><div class="manager-card-stats">'+(Number.isFinite(m.ownershipPct)?'<span>공시 기반 지분율</span><strong>'+m.ownershipPct.toFixed(2)+'%</strong>':'<span>'+quarter(m.period)+'</span><strong>'+compact(m.totalValue??m.value_usd)+'</strong>'+(m.holdingCount?'<small>공시 보유 '+count(m.holdingCount)+'개</small>':m.verified?'<small>'+count(m.shares)+'주 보유 · '+esc(m.filedAt)+' 제출</small>':''))+'</div><span class="manager-card-arrow">'+icon('chevron')+'</span></a>').join('');}
 async function stockOwners(ticker,poll=false){clearTimeout(ownerTimer);state.ticker=ticker;const results=content.querySelector('.manager-results');if(!poll)results.innerHTML=stateBox(ticker+' 최신 공시의 주식 보유를 확인하고 있어요',true);content.querySelector('.manager-pagination').innerHTML='';
  try{const d=await request('/api/managers/stock?ticker='+encodeURIComponent(ticker));if(!d)return;content.querySelector('.manager-search-context').innerHTML='<div class="section-heading"><h2>'+esc(ticker)+' 보유 운용사</h2><a data-nav href="/stock/US/'+encodeURIComponent(ticker)+'">종목 상세 '+icon('chevron')+'</a></div><p class="manager-note">'+esc(d.coverage)+'</p>'+(d.warning||d.verification?.failed?'<p class="manager-warning">'+esc(d.warning||d.message)+'</p>':'');results.innerHTML=(d.items.length?managerCards(d.items):stateBox(d.status==='checking'?'공시 대조 중 · '+d.verification.checked+' / '+d.verification.total:d.message||'확인된 주식 보유 운용사가 없습니다',d.status==='checking'))+(d.items.length&&d.status==='checking'?'<p class="manager-note">공시 대조 중 · '+d.verification.checked+' / '+d.verification.total+'</p>':'');if(d.status==='checking')ownerTimer=setTimeout(()=>{if(!destroyed&&state.ticker===ticker)stockOwners(ticker,true);},800);}
  catch(e){if(e.name!=='AbortError'&&!destroyed)results.innerHTML=stateBox(e.message)+'<button class="secondary-button" data-manager="retry">다시 시도</button>';}
 }
 async function search(){clearTimeout(ownerTimer);state.ticker=null;const results=content.querySelector('.manager-results');content.querySelector('.manager-search-context').innerHTML='';content.querySelector('.manager-pagination').innerHTML='';
  if(state.mode==='stock'&&!state.q){controller?.abort();requestVersion++;results.innerHTML=stateBox('미국 종목명이나 티커를 입력해 주세요');return;}
  results.innerHTML=stateBox(state.mode==='stock'?'종목을 찾고 있어요':'운용사를 찾고 있어요',true);
  try{const d=await request((state.mode==='stock'?'/api/managers/stocks?':'/api/managers?')+new URLSearchParams({q:state.q,page:String(state.page)}));if(!d)return;
   if(state.mode==='stock'){results.innerHTML=d.items.length?d.items.map(m=>'<button class="surface manager-stock-pick" data-manager="stock" data-ticker="'+esc(m.ticker)+'"><span class="stock-avatar">'+esc(m.ticker.slice(0,2))+'</span><span><strong>'+esc(m.name)+'</strong><small>'+esc(m.ticker)+' · 미국</small></span><span>보유 운용사 '+icon('chevron')+'</span></button>').join(''):stateBox(d.status==='empty'?'검색 결과가 없습니다':d.message||'종목 정보를 불러오지 못했습니다');return;}
   nextPage=d.nextPage;results.innerHTML=d.items.length?managerCards(d.items):stateBox('검색 결과가 없습니다');
   content.querySelector('.manager-pagination').innerHTML='<button data-manager="previous" '+(state.page===1?'disabled':'')+'>이전</button><span>'+state.page+' 페이지</span><button data-manager="next" '+(!nextPage?'disabled':'')+'>다음</button>';
  }catch(e){if(e.name!=='AbortError'&&!destroyed)results.innerHTML=stateBox(e.message)+'<button class="secondary-button" data-manager="retry">다시 시도</button>';}
 }
 function rowHtml(r,disposed=false){const weight=data.totalValue?r.valueUsd/data.totalValue*100:0;return '<tr><td class="holding-name">'+link(r)+'<small>'+esc(r.titleOfClass)+'</small></td><td data-label="섹터">'+esc(r.sector||'분류 미제공')+'</td><td class="numeric" data-label="'+(disposed?'직전 보유 수':'보유 수')+'">'+count(disposed?r.previousShares:r.shares)+'</td><td class="numeric" data-label="전 분기 대비 증감률"><span class="holding-change '+r.changeType+'">'+(loadingComparison&&r.changeType==='unknown'?'확인 중':changes[r.changeType])+'</span><small>'+pct(r.shareChangePct)+'</small></td><td class="numeric" data-label="평가액">'+money(disposed?r.previousValueUsd:r.valueUsd)+'</td><td class="numeric" data-label="'+(disposed?'이전 대비':'공시 비중')+'">'+(disposed?pct(r.shareChangePct):weight.toFixed(2)+'%')+'</td>'+(!disposed&&data.priceAvailability?.enabled?'<td class="numeric" data-label="최근 1개월 주가">'+pct(r.priceChanges?.month1)+'<small>'+esc(r.priceChanges?.asOf||'가격 이력 없음')+'</small></td><td class="numeric" data-label="최근 3개월 주가">'+pct(r.priceChanges?.month3)+'</td>':'')+'</tr>';}
 function table(rows,disposed=false){return '<div class="manager-table-scroll" tabindex="0" role="region" aria-label="'+(disposed?'전량 처분':'보유 종목')+' 표"><table class="manager-table"><thead><tr><th>종목 · 종류</th><th>섹터</th><th class="numeric">'+(disposed?'전 분기 보유 수':state.kind==='principal'?'원금 수량':'보유 주식 수')+'</th><th class="numeric">전 분기 대비 증감률</th><th class="numeric">'+(disposed?'전 분기 평가액':'공시 평가액')+'</th><th class="numeric">'+(disposed?'변화율':'공시 비중')+'</th>'+(!disposed&&data.priceAvailability?.enabled?'<th class="numeric">최근 1개월 주가</th><th class="numeric">최근 3개월 주가</th>':'')+'</tr></thead><tbody>'+rows.map(r=>rowHtml(r,disposed)).join('')+'</tbody></table></div>';}
 function pageTable(rows,disposed=false){const key=disposed?'disposedPage':'holdingPage',pages=Math.max(1,Math.ceil(rows.length/100));state[key]=Math.min(state[key],pages);const start=(state[key]-1)*100;
  return table(rows.slice(start,start+100),disposed)+'<div class="manager-pagination holding-pagination"><button data-manager="holding-page" data-list="'+key+'" data-step="-1" '+(state[key]===1?'disabled':'')+'>이전</button><span>'+count(start+1)+'–'+count(Math.min(start+100,rows.length))+' / '+count(rows.length)+'개</span><button data-manager="holding-page" data-list="'+key+'" data-step="1" '+(state[key]===pages?'disabled':'')+'>다음</button></div>';
 }
 function renderHoldings(){const active=Object.entries({검색:state.holdingQuery,섹터:state.sector,상태:state.change==='all'?'':changes[state.change],최소비중:state.weightMin,최대비중:state.weightMax,최소보유액:state.valueMin,최대보유액:state.valueMax}).filter(([,v])=>v!==''&&v!=null);const applied=content.querySelector('.manager-holding-applied');if(applied)applied.innerHTML='<span>'+esc(active.map(([k,v])=>k+': '+v).join(' · ')||'전체 조건')+'</span><button data-manager="reset-holdings">초기화</button>';saveFilters();const panel=content.querySelector('.manager-holdings-results');if(!panel)return;const rows=filterHoldings(data,state);
  panel.innerHTML=rows.length?pageTable(rows,state.change==='disposed'):stateBox('조건에 맞는 보유 종목이 없습니다');content.querySelector('.manager-holdings-count').textContent=count(rows.length)+'개';
  const disposed=data.disposed.filter(r=>r.kind===state.kind);content.querySelector('.manager-disposed').innerHTML='<div class="section-heading"><h2>전량 처분 <span>'+disposed.length+'</span></h2><small>직전 분기에는 보유, 이번 공시에서는 미보유</small></div>'+(disposed.length?pageTable(disposed,true):stateBox(loadingComparison?'전 분기 공시 확인 중':data.comparable?'전량 처분 종목이 없습니다':'직전 분기 비교 자료가 없어 판정할 수 없습니다'));
 }
 function renderVisuals(){const map=content.querySelector('.manager-treemap');if(!map||destroyed)return;const rows=data.items.filter(r=>r.kind===state.kind&&r.valueUsd>0),rect=map.getBoundingClientRect();
  
  const layout=treemapLayout(rows.map(r=>({...r,marketCap:r.valueUsd})),0,0,100,100,Math.max(rect.width,300)/Math.max(rect.height,300));
  mapLayout=layout;
  if(!data.policy?.treemap)map.innerHTML=stateBox('트리맵 표시 권한 확인 필요');
  else if(!layout.length)map.innerHTML=stateBox('이 종류의 보유 내역이 없습니다');
  else{
   // Paint every security at its true filing-value area without thousands of DOM nodes.
   map.innerHTML='<canvas role="img" aria-label="전체 보유 종목 맵. 개별 종목은 아래 보유 종목 표에서도 찾을 수 있습니다."></canvas>';
   const canvas=map.querySelector('canvas'),scale=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*scale);canvas.height=Math.round(rect.height*scale);const ctx=canvas.getContext('2d');ctx.scale(scale,scale);
   const colors={new:'#ad353e',increased:'#e65061',reduced:'#437dec',unchanged:'#e4e9ee',unknown:'#dce3ea'};
   for(const r of layout){const x=r.x*rect.width/100,y=r.y*rect.height/100,w=r.w*rect.width/100,h=r.h*rect.height/100;ctx.fillStyle=colors[r.changeType];ctx.fillRect(x,y,w,h);ctx.strokeStyle='#fff';ctx.lineWidth=.5;ctx.strokeRect(x,y,w,h);
    if(w>=52&&h>=36){const a=document.createElement(r.ticker?'a':'span');a.className='manager-map-label '+r.changeType;if(r.ticker){a.href='/stock/US/'+encodeURIComponent(r.ticker);a.dataset.nav='';}a.style.cssText='left:'+r.x+'%;top:'+r.y+'%;width:'+r.w+'%;height:'+r.h+'%';a.innerHTML='<strong>'+esc(r.ticker||r.name)+'</strong><span>'+esc(loadingComparison?'확인 중':r.changeType==='new'?'신규':pct(r.shareChangePct))+'</span>';a.title=(r.ticker||r.name)+' · '+money(r.valueUsd)+' · '+changes[r.changeType];map.append(a);}
   }
  }
  const quarters=data.history.find(x=>x.kind===state.kind)?.quarters||[],names=[...new Set(quarters.flatMap(x=>x.sectors.map(s=>s.name)))];
  content.querySelector('.manager-sector-trend').innerHTML=quarters.length?quarters.map(q=>'<div class="manager-sector-quarter"><strong>'+quarter(q.period)+'</strong><div class="manager-sector-stack" aria-label="'+quarter(q.period)+' 섹터 비중">'+q.sectors.map(s=>'<span tabindex="0" style="width:'+s.weight+'%;background:'+sectorColor(s.name)+'" title="'+esc(s.name+' · '+s.weight.toFixed(2)+'% · '+money(s.value))+'" aria-label="'+esc(s.name+' '+s.weight.toFixed(2)+'%')+'">'+(s.weight>=16?s.weight.toFixed(1)+'%':'')+'</span>').join('')+'</div></div>').join('')+'<div class="manager-sector-key">'+names.map(name=>'<span><i style="background:'+sectorColor(name)+'"></i>'+esc(name)+'</span>').join(''):'<div class="data-state">섹터 비중 추이 데이터가 없습니다</div>';
 }
 function detail(){const kindCounts=Object.fromEntries(Object.keys(kinds).map(k=>[k,data.items.filter(r=>r.kind===k).length]));
  root.querySelector('h1').textContent='운용사 보유 현황';
  content.innerHTML='<a class="back-button" href="/managers" data-nav>'+icon('arrow')+' 운용사 검색</a><section class="surface manager-summary"><div class="manager-detail-heading"><div><span class="manager-period">'+(state.period?'공시 보유 현황':'최근 공시 보유 현황')+' · '+quarter(data.period)+' 기준</span><h2>'+esc(data.manager.name)+'</h2><p>'+esc(data.manager.people.join(' · '))+'<span>CIK '+esc(data.manager.cik.padStart(10,'0'))+'</span></p></div><button data-manager="retry" class="icon-button" aria-label="공시 다시 확인">'+icon('refresh')+'</button></div><div class="manager-metrics"><div><span>공시상 총 보유액</span><strong>'+compact(data.totalValue)+'</strong><small>'+money(data.totalValue)+'</small></div><div><span>보유 증권 수</span><strong>'+count(data.holdingCount)+'<small>개</small></strong><small>주식·옵션 구분 집계</small></div><div><span>공시 제출일</span><strong>'+esc(data.filedAt)+'</strong><small>'+(data.amended?'수정 공시 반영':'13F-HR')+'</small></div><div><span>보유 기준일</span><strong>'+esc(data.period)+'</strong><small>분기 말 공시 기준</small></div></div></section><p class="manager-background-status manager-note" role="status" hidden></p>'+(data.warning?'<p class="manager-warning" role="status">'+esc(data.warning)+'</p>':'')+(data.confidential?'<p class="manager-warning">비공개 보유 항목이 있어 신규·전량 처분 비교를 표시하지 않습니다.</p>':'')+'<div class="manager-kind-tabs" role="group" aria-label="증권 종류">'+Object.entries(kinds).map(([k,label])=>'<button data-manager="kind" data-kind="'+k+'" aria-pressed="'+(state.kind===k)+'" class="'+(state.kind===k?'active':'')+'">'+label+' <span>'+kindCounts[k]+'</span></button>').join('')+'</div><div class="manager-visual-grid"><section class="surface manager-map-panel"><div class="section-heading"><h2>보유 종목 맵</h2><small>면적 · 공시 평가액</small></div><div class="manager-treemap" aria-label="공시 평가액에 따른 보유 종목 트리맵"></div><div class="manager-change-legend"><span class="new">신규</span><span class="increased">수량 증가</span><span class="reduced">수량 감소</span><span class="unchanged">유지</span><span class="unknown">비교 불가</span></div></section><section class="surface manager-sector-panel"><div class="section-heading"><h2>섹터 비중 추이</h2><small>선택한 증권 종류 기준</small></div><div class="manager-sector-trend"></div><p class="manager-note">Finviz 공시 분류 · 각 분기 공시 평가액 비중</p></section></div><section class="surface manager-holdings"><div class="section-heading"><h2>보유 종목 <span class="manager-holdings-count"></span></h2><small>수량 비교에는 주식 분할 등도 포함될 수 있습니다</small></div><div class="manager-holdings-tools"><input type="search" aria-label="보유 종목 검색" placeholder="종목명·티커·CUSIP 검색" class="manager-holding-search"><select aria-label="보유 수 변화 필터" class="manager-change-filter"><option value="all">전체 변화</option>'+['new','increased','reduced','unchanged','disposed','unknown'].map(k=>'<option value="'+k+'">'+changes[k]+'</option>').join('')+'</select><select aria-label="보유 종목 정렬" class="manager-sort"><option value="value">평가액순</option><option value="change">보유 수 증감률순</option></select></div><div class="manager-holdings-results"></div></section><section class="surface manager-disposed"></section><footer class="manager-source"><span>SEC 13F · 최근 확인 '+new Date(data.receivedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' KST</span><div>'+data.filings.map(f=>'<a href="'+esc(f.url)+'" target="_blank" rel="noopener noreferrer">'+esc(f.form)+' · '+esc(f.filedAt)+' ↗</a>').join('')+'</div><small>옵션 수량은 공시에 기재된 기초 주식 수입니다. 공시로 확인되지 않은 현재 보유·매매 내역은 포함하지 않습니다.</small></footer>';
  const periodLabel=document.createElement('label');periodLabel.className='manager-period-picker';periodLabel.innerHTML='공시 분기 <select aria-label="공시 분기 선택" class="manager-period-select"><option value="">최신 공시</option>'+(data.availablePeriods||[]).map(p=>'<option value="'+p+'">'+quarter(p)+'</option>').join('')+'</select>';content.querySelector('.manager-summary').append(periodLabel);periodLabel.querySelector('select').value=state.period;
  const filters=document.createElement('details');filters.className='manager-advanced';filters.open=!!(state.sector||state.weightMin||state.weightMax||state.valueMin||state.valueMax);filters.innerHTML='<summary>보유 종목 상세 조건</summary><div class="manager-filter-grid"><label>섹터<select data-holding-filter="sector"><option value="">전체 섹터</option>'+[...new Set(data.items.map(r=>r.sector||'분류 미제공'))].sort().map(s=>'<option value="'+esc(s)+'">'+esc(s)+'</option>').join('')+'</select></label>'+[['weightMin','최소 공시 비중 (%)'],['weightMax','최대 공시 비중 (%)'],['valueMin','최소 공시 보유액 ($)'],['valueMax','최대 공시 보유액 ($)']].map(([k,label])=>'<label>'+label+'<input type="number" min="0" '+(k.startsWith('weight')?'max="100"':'')+' step="any" data-holding-filter="'+k+'" placeholder="제한 없음"></label>').join('')+'</div><p class="manager-note">보통주·ETF 세부 분류 미제공 · 주식과 풋/콜 옵션은 구분합니다.</p>';
  content.querySelector('.manager-holdings-tools').after(filters);for(const c of filters.querySelectorAll('[data-holding-filter]'))c.value=state[c.dataset.holdingFilter];
  const sort=content.querySelector('.manager-sort');sort.insertAdjacentHTML('beforeend','<option value="weight">공시 비중순</option><option value="month1" '+(!data.priceAvailability?.enabled?'disabled':'')+'>최근 1개월 주가 등락률순</option><option value="month3" '+(!data.priceAvailability?.enabled?'disabled':'')+'>최근 3개월 주가 등락률순</option>');
  const applied=document.createElement('div');applied.className='manager-holding-applied';filters.after(applied);
  const priceNote=document.createElement('p');priceNote.className='manager-note';priceNote.textContent=data.priceAvailability?.reason||'최근 주가 등락률은 가격 이력 연결 후 표시합니다.';content.querySelector('.manager-holdings').append(priceNote);
  content.querySelector('.manager-sort').value=state.sort;content.querySelector('.manager-holding-search').value=state.holdingQuery;content.querySelector('.manager-change-filter').value=state.change;renderHoldings();resize?.disconnect();resize=new ResizeObserver(renderVisuals);resize.observe(content.querySelector('.manager-treemap'));renderVisuals();
 }
 async function loadDetail(){resize?.disconnect();loadingComparison=true;content.innerHTML=stateBox('최신 보유 공시를 불러오고 있어요',true);try{
  data=await request('/api/managers/'+cik+'?quarters='+(state.period?'4':'1')+(state.period?'&period='+state.period:''));if(!data)return;if(data.status!=='ready'){content.innerHTML=stateBox(data.message||'공개된 보유 공시가 없습니다');return;}
  document.title=data.manager.name+' · 운용사 보유 현황';if(state.period){loadingComparison=false;detail();return;}detail();const note=content.querySelector('.manager-background-status');note.hidden=false;note.textContent='보유 내역 조회 완료 · 전 분기 비교와 섹터 추이를 불러오는 중';
  try{const full=await request('/api/managers/'+cik+'?quarters=4');if(!full)return;data=full;loadingComparison=false;detail();const current=content.querySelector('.manager-background-status');current.hidden=!data.warning;current.textContent=data.warning||'';}
  catch(e){if(e.name!=='AbortError'&&!destroyed){loadingComparison=false;renderHoldings();content.querySelector('.manager-background-status').textContent='이전 분기 조회 실패 · 최신 보유 내역을 표시합니다.';}}
 }catch(e){if(e.name!=='AbortError'&&!destroyed)content.innerHTML=stateBox(e.name==='TimeoutError'?'공시 조회 시간이 초과되었습니다. 다시 시도해 주세요.':e.message)+'<button class="secondary-button" data-manager="retry">다시 시도</button>';}}
 const click=e=>{const b=e.target.closest('[data-manager]');if(!b)return;switch(b.dataset.manager){case 'reset-holdings':Object.assign(state,{holdingQuery:'',sector:'',weightMin:'',weightMax:'',valueMin:'',valueMax:'',change:'all',sort:'value',holdingPage:1});detail();break;case 'retry':cik?loadDetail():state.ticker?stockOwners(state.ticker):search();break;case 'mode':if(b.dataset.mode==='manager'){location.href='/managers';return;}clearTimeout(searchTimer);state.mode=b.dataset.mode;state.q='';state.page=1;searchShell();search();break;case 'stock':clearTimeout(searchTimer);stockOwners(b.dataset.ticker);break;case 'holding-page':state[b.dataset.list]+=Number(b.dataset.step);renderHoldings();break;case 'example':state.q=b.dataset.query;state.page=1;content.querySelector('#manager-search').value=state.q;search();break;case 'previous':state.page=Math.max(1,state.page-1);search();break;case 'next':if(nextPage){state.page=nextPage;search();}break;case 'kind':state.kind=b.dataset.kind;state.holdingPage=1;state.disposedPage=1;state.change='all';state.holdingQuery='';detail();break;}};
 const submit=e=>{clearTimeout(searchTimer);if(e.target.matches('.manager-search-form')){e.preventDefault();state.q=content.querySelector('#manager-search').value.trim();state.page=1;search();}};
 const input=e=>{if(e.target.dataset.holdingFilter&&e.target.checkValidity()){state[e.target.dataset.holdingFilter]=e.target.value;state.holdingPage=1;renderHoldings();return;}if(e.target.matches('.manager-holding-search')){state.holdingQuery=e.target.value;state.holdingPage=1;renderHoldings();}if(e.target.id==='manager-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.q=e.target.value.trim();state.page=1;search();},350);}};
 const change=e=>{if(e.target.matches('.manager-period-select')){state.period=e.target.value;saveFilters();loadDetail();return;}if(e.target.dataset.holdingFilter){if(!e.target.checkValidity())return;state[e.target.dataset.holdingFilter]=e.target.value;state.holdingPage=1;renderHoldings();return;}if(e.target.matches('.manager-change-filter'))state.change=e.target.value;else if(e.target.matches('.manager-sort'))state.sort=e.target.value;else return;state.holdingPage=1;renderHoldings();};
 const mapItem=e=>{const canvas=e.target.closest('.manager-treemap canvas');if(!canvas)return null;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;return mapLayout.find(t=>x>=t.x&&x<t.x+t.w&&y>=t.y&&y<t.y+t.h);};
 const mapMove=e=>{const item=mapItem(e);if(item)e.target.title=(item.ticker||item.name)+' · '+money(item.valueUsd)+' · '+changes[item.changeType];};
 const mapClick=e=>{const item=mapItem(e);if(item?.ticker){const a=document.createElement('a');a.href='/stock/US/'+encodeURIComponent(item.ticker);a.dataset.nav='';a.hidden=true;root.append(a);a.click();a.remove();}};
 root.addEventListener('pointermove',mapMove);root.addEventListener('click',mapClick);
 root.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('input',input);root.addEventListener('change',change);
 if(cik)loadDetail();else{searchShell();search();}
 return {destroy(){destroyed=true;root.removeEventListener('pointermove',mapMove);root.removeEventListener('click',mapClick);controller?.abort();resize?.disconnect();clearTimeout(searchTimer);clearTimeout(ownerTimer);root.removeEventListener('click',click);root.removeEventListener('submit',submit);root.removeEventListener('input',input);root.removeEventListener('change',change);}};
}
export function mountStockManagers(root,{market,id}){
 if(market!=='US'){root.hidden=true;return {destroy(){}};}let destroyed=false,timer;const controller=new AbortController();root.className='surface stock-managers';root.innerHTML='<div class="section-heading"><h2>이 종목을 보유한 운용사</h2><a data-nav href="/managers">운용사 검색 '+icon('chevron')+'</a></div><div class="stock-manager-results">'+stateBox('최신 공시의 주식 보유 확인 중',true)+'</div>';
 async function load(){try{
  const r=await fetch('/api/managers/stock?ticker='+encodeURIComponent(id),{signal:controller.signal});const d=await r.json();if(!r.ok)throw new Error(d.message);if(destroyed)return;
  const checking=d.status==='checking';root.querySelector('.stock-manager-results').innerHTML='<p class="manager-note">'+esc(d.coverage)+'</p>'+(d.items.length?'<div class="stock-manager-list">'+d.items.map(m=>'<a data-nav href="/managers/'+m.cik+'?holding='+encodeURIComponent(id)+'"><span><strong>'+esc(m.name)+'</strong><small>CIK '+esc(m.cik.padStart(10,'0'))+' · '+quarter(m.period)+'</small></span><span><strong>'+count(m.shares)+'주</strong><small>'+money(m.value_usd)+'</small></span></a>').join('')+'</div>':stateBox(checking?'주식 보유 공시 대조 중':d.message||'확인된 주식 보유 운용사가 없습니다',checking))+(checking?'<p class="manager-note">공시 확인 '+d.verification.checked+' / '+d.verification.total+'</p>':d.verification.failed?'<p class="manager-note">'+esc(d.message)+'</p>':'');
  if(checking)timer=setTimeout(load,800);
 }catch(e){if(!destroyed&&e.name!=='AbortError')root.querySelector('.stock-manager-results').innerHTML=stateBox('보유 운용사를 불러오지 못했습니다');}}
 load();return {destroy(){destroyed=true;clearTimeout(timer);controller.abort();}};
}
